	skill_id, parent_id, name, type, file_type, content, locked, sort, add_time, update_time
) VALUES (
	 #{skillId}, #{parentId}, #{name}, #{type}, #{fileType}, #{content}, #{locked}, #{sort}, NOW(), NOW()
 );

