mapper.select:
SELECT 
FROM xxl_ai_skill_file AS t
WHERE t.id = #{id}

SELECT 
FROM xxl_ai_skill_file AS t
WHERE t.skill_id = #{skillId}
	AND t.parent_id = #{parentId}
ORDER BY t.type ASC, t.sort ASC, t.id ASC

SELECT count(1)
FROM xxl_ai_skill_file AS t
WHERE t.skill_id = #{skillId}
	AND t.parent_id = #{parentId}
	AND t.name = #{name}

	AND t.id != #{excludeId}

SELECT count(1)
FROM xxl_ai_skill_file AS t
WHERE t.skill_id = #{skillId}
